'e_enum_reckon.gateway.v1.SubscriptionType'('SUBSCRIPTION_TYPE_EVENT_TYPE', Bin, _TrUserData) -> <<Bin/binary, 2>>;
'e_enum_reckon.gateway.v1.SubscriptionType'('SUBSCRIPTION_TYPE_EVENT_PATTERN', Bin, _TrUserData) -> <<Bin/binary, 3>>;
