read_group(Bin, FieldNum) ->
    {NumBytes, EndTagLen} = read_gr_b(Bin, 0, 0, 0, 0, FieldNum),
    <<Group:NumBytes/binary, _:EndTagLen/binary, Rest/binary>> = Bin,
    {Group, Rest}.

%% Like skipping over fields, but record the total length,
%% Each field is <(FieldNum bsl 3) bor FieldType> ++ <FieldValue>
%% Record the length because varints may be non-optimally encoded.
%%
%% Groups can be nested, but assume the same FieldNum cannot be nested
%% because group field numbers are shared with the rest of the fields
%% numbers. Thus we can search just for an group-end with the same
%% field number.
%%
%% (The only time the same group field number could occur would
%% be in a nested sub message, but then it would be inside a
%% length-delimited entry, which we skip-read by length.)
read_gr_b(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen, FieldNum)
  when N < (32-7) ->
    read_gr_b(Tl, N+7, X bsl N + Acc, NumBytes, TagLen+1, FieldNum);
read_gr_b(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen,
          FieldNum) ->
    Key = X bsl N + Acc,
    TagLen1 = TagLen + 1,
    case {Key bsr 3, Key band 7} of
        {FieldNum, 4} -> % 4 = group_end
            {NumBytes, TagLen1};
        {_, 0} -> % 0 = varint
            read_gr_vi(Tl, 0, NumBytes + TagLen1, FieldNum);
        {_, 1} -> % 1 = bits64
            <<_:64, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 8, 0, FieldNum);
        {_, 2} -> % 2 = length_delimited
            read_gr_ld(Tl, 0, 0, NumBytes + TagLen1, FieldNum);
        {_, 3} -> % 3 = group_start
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 4} -> % 4 = group_end
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 5} -> % 5 = bits32
            <<_:32, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 4, 0, FieldNum)
    end.

read_gr_vi(<<1:1, _:7, Tl/binary>>, N, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_vi(Tl, N+7, NumBytes+1, FieldNum);
read_gr_vi(<<0:1, _:7, Tl/binary>>, _, NumBytes, FieldNum) ->
    read_gr_b(Tl, 0, 0, NumBytes+1, 0, FieldNum).

read_gr_ld(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_ld(Tl, N+7, X bsl N + Acc, NumBytes+1, FieldNum);
read_gr_ld(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum) ->
    Len = X bsl N + Acc,
    NumBytes1 = NumBytes + 1,
    <<_:Len/binary, Tl2/binary>> = Tl,
    read_gr_b(Tl2, 0, 0, NumBytes1 + Len, 0, FieldNum).

merge_msgs(Prev, New, MsgName) when is_atom(MsgName) -> merge_msgs(Prev, New, MsgName, []).

merge_msgs(Prev, New, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        append_events_request -> merge_msg_append_events_request(Prev, New, TrUserData);
        read_stream_request -> merge_msg_read_stream_request(Prev, New, TrUserData);
        get_stream_version_request -> merge_msg_get_stream_version_request(Prev, New, TrUserData);
        list_streams_request -> merge_msg_list_streams_request(Prev, New, TrUserData);
        delete_stream_request -> merge_msg_delete_stream_request(Prev, New, TrUserData);
        read_by_event_types_request -> merge_msg_read_by_event_types_request(Prev, New, TrUserData);
        read_by_tags_request -> merge_msg_read_by_tags_request(Prev, New, TrUserData);
        read_all_global_request -> merge_msg_read_all_global_request(Prev, New, TrUserData);
        append_events_response -> merge_msg_append_events_response(Prev, New, TrUserData);
        read_stream_response -> merge_msg_read_stream_response(Prev, New, TrUserData);
        get_stream_version_response -> merge_msg_get_stream_version_response(Prev, New, TrUserData);
        list_streams_response -> merge_msg_list_streams_response(Prev, New, TrUserData);
        delete_stream_response -> merge_msg_delete_stream_response(Prev, New, TrUserData);
        proposed_event -> merge_msg_proposed_event(Prev, New, TrUserData);
        recorded_event -> merge_msg_recorded_event(Prev, New, TrUserData);
        snapshot_record -> merge_msg_snapshot_record(Prev, New, TrUserData);
        subscription_info -> merge_msg_subscription_info(Prev, New, TrUserData)
    end.

-compile({nowarn_unused_function,merge_msg_append_events_request/3}).
merge_msg_append_events_request(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{store_id := NFstore_id}} -> S1#{store_id => NFstore_id};
             {#{store_id := PFstore_id}, _} -> S1#{store_id => PFstore_id};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{stream_id := NFstream_id}} -> S2#{stream_id => NFstream_id};
             {#{stream_id := PFstream_id}, _} -> S2#{stream_id => PFstream_id};
             _ -> S2
         end,
    S4 = case {PMsg, NMsg} of
             {_, #{expected_version := NFexpected_version}} -> S3#{expected_version => NFexpected_version};
             {#{expected_version := PFexpected_version}, _} -> S3#{expected_version => PFexpected_version};
             _ -> S3
         end,
    case {PMsg, NMsg} of
        {#{events := PFevents}, #{events := NFevents}} -> S4#{events => 'erlang_++'(PFevents, NFevents, TrUserData)};
        {_, #{events := NFevents}} -> S4#{events => NFevents};
        {#{events := PFevents}, _} -> S4#{events => PFevents};
        {_, _} -> S4
    end.

