verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        append_events_request -> v_msg_append_events_request(Msg, [MsgName], TrUserData);
        read_stream_request -> v_msg_read_stream_request(Msg, [MsgName], TrUserData);
        get_stream_version_request -> v_msg_get_stream_version_request(Msg, [MsgName], TrUserData);
        list_streams_request -> v_msg_list_streams_request(Msg, [MsgName], TrUserData);
        delete_stream_request -> v_msg_delete_stream_request(Msg, [MsgName], TrUserData);
        read_by_event_types_request -> v_msg_read_by_event_types_request(Msg, [MsgName], TrUserData);
        read_by_tags_request -> v_msg_read_by_tags_request(Msg, [MsgName], TrUserData);
        read_all_global_request -> v_msg_read_all_global_request(Msg, [MsgName], TrUserData);
        append_events_response -> v_msg_append_events_response(Msg, [MsgName], TrUserData);
        read_stream_response -> v_msg_read_stream_response(Msg, [MsgName], TrUserData);
        get_stream_version_response -> v_msg_get_stream_version_response(Msg, [MsgName], TrUserData);
        list_streams_response -> v_msg_list_streams_response(Msg, [MsgName], TrUserData);
        delete_stream_response -> v_msg_delete_stream_response(Msg, [MsgName], TrUserData);
        proposed_event -> v_msg_proposed_event(Msg, [MsgName], TrUserData);
        recorded_event -> v_msg_recorded_event(Msg, [MsgName], TrUserData);
        snapshot_record -> v_msg_snapshot_record(Msg, [MsgName], TrUserData);
        subscription_info -> v_msg_subscription_info(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


